/** Inventory rows derived/stored per grade */
export let inventoryDb = productsDb.flatMap((p) =>
  p.grades.map((g) => ({
    id: `inv-${p.id}-${g.id}`,
    vendorId: p.vendorId,
    managerId: p.managerId,
    farmerId: p.farmerId,
    productId: p.id,
    productName: p.name,
    gradeId: g.id,
    grade: g.label,
    unit: p.unit,
    currentStock: g.quantity,
    reservedStock: Math.round(g.quantity * 0.1),
    soldStock: Math.round(g.quantity * 0.3),
    totalStock: g.quantity + Math.round(g.quantity * 0.1) + Math.round(g.quantity * 0.3),
    status: g.quantity <= 0 ? 'Out of Stock' : g.quantity < 20 ? 'Low Stock' : 'In Stock',
    lastUpdated: p.updatedAt,
  })),
)

